/bin/bash -lc "node <<'EOF'
const { execFileSync } = require('node:child_process');

const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
function randomString(length) {
  let result = '';
  for (let i = 0; i < length; i += 1) {
    result += alphabet[Math.floor(Math.random() * alphabet.length)];
  }
  return result;
}

for (const keyLength of [16, 24, 32]) {
  for (const dataLength of [16, 32, 48]) {
    for (let attempt = 0; attempt < 4; attempt += 1) {
      const key = randomString(keyLength);
      const data = randomString(dataLength);
      const expected = execFileSync('/workspace/dataset/test16_executable', ['--key', key, '--data', data], { encoding: 'utf8' });
      const actual = execFileSync('node', ['/output/test16.mjs', '--key', key, '--data', data], { encoding: 'utf8' });
      if (expected "'!== actual) {
        console.error('"'Mismatch', { keyLength, dataLength, key, data, expected, actual });
        process.exit(1);
      }
    }
  }
}

console.log('randomized parity checks passed');
EOF"

