/bin/bash -lc "node <<'EOF'
const { execFileSync } = require('node:child_process');
const checks = [
  ['--ke', '1234567890123456', '--da', '1234567890123456'],
  ['--key=123456789012345678901234', '--data=1234567890123456'],
  ['--key', '1234567890123456', '--data', '123456789012345'],
];
for (const args of checks) {
  const expected = (() => {
    try {
      return execFileSync('/workspace/dataset/test16_executable', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    } catch (error) {
      return "'`${error.status}'"\\n"'${error.stderr.toString()}`;
    }
  })();
  const actual = (() => {
    try {
      return execFileSync('"'node', ['/output/test16.mjs', ...args], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    } catch (error) {
      return "'`${error.status}'"\\n"'${error.stderr.toString()}`;
    }
  })();
  if (args[0] === '"'--key' && args[3] === '123456789012345') {
    if ("'!actual.includes('"'ValueError: plaintext block must be 16 bytes')) {
      console.error('block error mismatch', actual);
      process.exit(1);
    }
  } else if (expected "'!== actual && !(expected.includes('"'ValueError: Invalid key size') && actual.includes('ValueError: Invalid key size'))) {
    console.error('Mismatch for args', args);
    console.error('Expected:', expected);
    console.error('Actual:', actual);
    process.exit(1);
  }
}
console.log('post-patch checks passed');
EOF"

